args.command:
perl -e '
use strict;
use warnings;
use File::Find;
use File::Basename;

my $root = "/bench/repo";
my $internal = "$root/internal";

# Collect declarations under internal/ (non-test)
my @decls; # {path, line, name, recv, pkg}
sub pkg_of {
  my ($path) = @_;
  open my $fh, "<", $path or return "";
  while (<$fh>) {
    return $1 if /^package\s+(\w+)/;
  }
  return "";
}

find({
  wanted => sub {
    return unless /\.go$/ && !/_test\.go$/;
    my $path = $File::Find::name;
    my $pkg = pkg_of($path);
    open my $fh, "<", $path or return;
    my $n = 0;
    while (my $line = <$fh>) {
      $n++;
      if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
        my $recv = $1 // "";
        my $name = $2;
        next if $name eq "init";
        push @decls, {path=>$path, line=>$n, name=>$name, recv=>$recv, pkg=>$pkg};
      }
    }
  },
  no_chdir => 1,
}, $internal);

print "decls: ", scalar(@decls), "\n";

# Collect all production .go files (exclude tests, proto/gen maybe include proto/gen? skip proto)
my @src;
find({
  wanted => sub {
    return unless /\.go$/ && !/_test\.go$/;
    my $p = $File::Find::name;
    return if $p =~ m{/proto/};
    return if $p =~ m{/\.git/};
    push @src, $p;
  },
  no_chdir => 1,
}, $root);

print "src files: ", scalar(@src), "\n";

# Read all source into memory as one blob per file with line numbers
my %file_lines;
for my $p (@src) {
  open my $fh, "<", $p or next;
  my @lines = <$fh>;
  $file_lines{$p} = \@lines;
}

# For each unique (pkg, name), count call sites.
# Call patterns:
#  - pkg.Name(  for exported package-level
#  - Name( in same package
#  - .Name( for methods
# Exclude the declaration line itself.

sub count_calls {
  my ($decl) = @_;
  my $name = $decl->{name};
  my $pkg = $decl->{pkg};
  my $decl_path = $decl->{path};
  my $decl_line = $decl->{line};
  my $is_method = $decl->{recv} ne "";
  my $exported = $name =~ /^[A-Z]/;
  my $count = 0;
  my @callers;
  for my $p (@src) {
    my $lines = $file_lines{$p};
    my $file_pkg = "";
    for my $line (@$lines) {
      if ($line =~ /^package\s+(\w+)/) { $file_pkg = $1; last; }
    }
    for my $i (0..$#$lines) {
      my $ln = $i+1;
      next if $p eq $decl_path && $ln == $decl_line;
      my $line = $lines->[$i];
      next if $line =~ /^\s*\/\//;
      next if $line =~ /^func\s+/; # skip other declarations of same name
      if ($is_method) {
        if ($line =~ /\.$name\s*\(/) {
          $count++;
          push @callers, "$p:$ln" if @callers < 8;
        }
      } else {
        if ($exported) {
          # qualified or same-package
          if ($line =~ /\b\Q$pkg\E\.\Q$name\E\s*\(/ || ($file_pkg eq $pkg && $line =~ /(?<![.\w])\Q$name\E\s*\(/)) {
            $count++;
            push @callers, "$p:$ln" if @callers < 8;
          }
        } else {
          if ($file_pkg eq $pkg && $line =~ /(?<![.\w])\Q$name\E\s*\(/) {
            $count++;
            push @callers, "$p:$ln" if @callers < 8;
          }
        }
      }
    }
  }
  return ($count, \@callers);
}

# Rank all decls
my @ranked;
for my $d (@decls) {
  my ($c, $callers) = count_calls($d);
  push @ranked, [$c, $d, $callers];
}
@ranked = sort { $b->[0] <=> $a->[0] } @ranked;

print "\nTOP 25:\n";
for my $i (0..24) {
  last if $i > $#ranked;
  my ($c, $d, $callers) = @{$ranked[$i]};
  my $recv = $d->{recv} ? "($d->{recv}) " : "";
  my $rel = $d->{path};
  $rel =~ s{^/bench/repo/}{};
  print sprintf("%3d  %s%s  %s:%d\n", $c, $recv, $d->{name}, $rel, $d->{line});
  for my $cl (@$callers) {
    $cl =~ s{^/bench/repo/}{};
    print "       e.g. $cl\n";
  }
}
'

