for my $p (@src) {
  open my $fh, "<", $p or next;
  my @lines = <$fh>;
  $file_lines{$p} = \@lines;
  for my $line (@lines) {
    if ($line =~ /^package\s+(\w+)/) { $file_pkg{$p} = $1; last; }
  }
}

sub count_calls {
  my ($decl) = @_;
  my $name = $decl->{name};
  my $pkg = $decl->{pkg};
  my $decl_path = $decl->{path};
  my $decl_line = $decl->{line};
  my $is_method = $decl->{recv} ne "";
  my $exported = $name =~ /^[A-Z]/;
  my $count = 0;
  my @callers;
  for my $p (@src) {
    my $lines = $file_lines{$p};
    my $file_pkg = $file_pkg{$p} // "";
    for my $i (0..$#$lines) {
      my $ln = $i+1;
      next if $p eq $decl_path && $ln == $decl_line;
      my $line = $lines->[$i];
      next if $line =~ /^\s*\/\//;
      next if $line =~ /^func\s+/;
      if ($is_method) {
        if ($line =~ /\.$name\s*\(/) {
          $count++;
          push @callers, "$p:$ln" if @callers < 6;
        }
      } else {
        if ($exported) {
          if ($line =~ /\b\Q$pkg\E\.\Q$name\E\s*\(/ || ($file_pkg eq $pkg && $line =~ /(?<![.\w])\Q$name\E\s*\(/)) {
            $count++;
            push @callers, "$p:$ln" if @callers < 6;
          }
        } else {
          if ($file_pkg eq $pkg && $line =~ /(?<![.\w])\Q$name\E\s*\(/) {
            $count++;
            push @callers, "$p:$ln" if @callers < 6;
          }
        }
      }
    }
  }
  return ($count, \@callers);
}

my @ranked;
for my $d (@decls) {
  my ($c, $callers) = count_calls($d);
  push @ranked, [$c, $d, $callers];
}
@ranked = sort { $b->[0] <=> $a->[0] } @ranked;

print "\nTOP 30:\n";
for my $i (0..29) {
  last if $i > $#ranked;
  my ($c, $d, $callers) = @{$ranked[$i]};
  my $recv = $d->{recv} ? "($d->{recv}) " : "";
  my $rel = $d->{path}; $rel =~ s{^/bench/repo/}{};
  print sprintf("%3d  %s%s  %s:%d\n", $c, $recv, $d->{name}, $rel, $d->{line});
  for my $cl (@$callers) {
    $cl =~ s{^/bench/repo/}{};
    print "       $cl\n";
  }
}
